public boolean attackEntityFromEggSack(DamageSource source, float amount) {
		if (super.hurt(source, amount)) {
			this.playSound(SoundEvents.WET_GRASS_PLACE, 1.0F, 0.6F + (this.random.nextFloat() - this.random.nextFloat()) * 0.4F);
			return true;
		}
		return false;
	}

@Override
	public void tick() {
		super.tick();

		Level world = this.level();
		RandomSource random = this.random;
		if (this.isDeadOrDying()) {
			if (!this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) && !this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT) && !world.isClientSide) {
				NetworkUtil.setPlayingAnimation(this, random.nextBoolean() ? EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT : EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT);
			}
			if (++this.deathTime >= 100) {
				if (!world.isClientSide) {
					ItemEntity elytra = this.spawnAtLocation(Items.ELYTRA);
					if (elytra != null) {
						elytra.setExtendedLifetime();
					}
					this.playSound(EESoundEvents.BROOD_EETLE_DEATH.get(), 2.0F, 0.9F + random.nextFloat() * 0.1F);
					this.discard();
					if (world instanceof ServerLevel serverLevel) {
						Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgressServer(), this.getEggCannonFlyingProgressServer(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
						serverLevel.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, EEBlocks.EETLE_EGG.get().defaultBlockState()), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 30, 0.3125F, 0.3125F, 0.3125F, 0.2D);
						serverLevel.sendParticles(new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 180, 61, 0.0F, 0.1F, Optional.of(0.15F)), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 2000, 0.3125F, 0.3125F, 0.3125F, 1.0D);
					}
				} else {
					for (int i = 0; i < 20; ++i) {
						world.addParticle(ParticleTypes.POOF, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D);
					}
				}
			} else if (world.isClientSide) {
				int deathTime = this.deathTime;
				if (deathTime == 30 || deathTime == 50 || deathTime == 70) {
					Vec3[] directionals = this.dyingParticleDirectionals = new Vec3[8];
					for (int i = 0; i < 8; i++) {
						double xOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
						double yOffset = random.nextDouble() * 1.5D;
						double zOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
						directionals[i] = new Vec3(xOffset, yOffset, zOffset);
					}
				}
				if (deathTime >= 35 && deathTime <= 85 && deathTime % 2 == 0 && ((deathTime - 35) % 20 + 20) % 20 <= 10) {
					Vec3[] dyingParticleDirectionals = this.dyingParticleDirectionals;
					if (dyingParticleDirectionals != null) {
						CorrockCrownParticleData dyingParticle = new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 30, 10, 1.0F, 0.05F, Optional.of(0.2F));
						Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgress(), this.getEggCannonFlyingProgress(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
						double minY = eggSackPos.y() - 0.4D;
						for (int i = 0; i < 8; i++) {
							Vec3 directional = dyingParticleDirectionals[i];
							double x = eggSackPos.x() + directional.x();
							double y = minY + directional.y();
							double z = eggSackPos.z() + directional.z();
							world.addParticle(dyingParticle, x, y, z, directional.x(), 0.5D + random.nextDouble() * 0.05D, directional.z());
						}
					}
				}
			}
		}

		if (!world.isClientSide) {
			if (this.idleDelay > 0) this.idleDelay--;
			if (this.slamCooldown > 0) this.slamCooldown--;
			if (this.eggCannonCooldown > 0) this.eggCannonCooldown--;
			if (this.flyCooldown > 0) this.flyCooldown--;
			if (this.eggDropOffCooldown > 0) this.eggDropOffCooldown--;

			if (random.nextFloat() < 0.005F && this.idleDelay <= 0 && this.onGround() && !this.isFiringCannon() && this.isNoEndimationPlaying()) {
				NetworkUtil.setPlayingAnimation(this, random.nextFloat() < 0.6F && !this.isFlying() ? EEPlayableEndimations.BROOD_EETLE_FLAP : EEPlayableEndimations.BROOD_EETLE_MUNCH);
				this.resetIdleFlapDelay();
			}

			BroodEggSack eggSackEntity = this.getEggSack(world);
			if (eggSackEntity != null && eggSackEntity.isAlive()) {
				eggSackEntity.xo = eggSackEntity.xOld = eggSackEntity.getX();
				eggSackEntity.yo = eggSackEntity.yOld = eggSackEntity.getY();
				eggSackEntity.zo = eggSackEntity.zOld = eggSackEntity.getZ();
				eggSackEntity.updatePosition(this);
			} else {
				eggSackEntity = new BroodEggSack(world);
				eggSackEntity.setBroodID(this.getId());
				eggSackEntity.updatePosition(this);
				world.addFreshEntity(eggSackEntity);
				this.setEggSackID(eggSackEntity.getId());
			}

			if (this.isFlying()) {
				this.ticksFlying++;

				if (this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_AIR_SLAM) && this.getAnimationTick() == 5 && (this.onGround() || !this.level().noCollision(DetectionHelper.checkOnGround(this.getBoundingBox(), 0.25F)))) {
					BroodEetleSlamGoal.slam(this, random, 1.0F);
				}
			} else {
				this.ticksFlying = 0;
			}

			if (this.level().getGameTime() % 5 == 0) {
				BlockPos takeoffPos = this.takeoffPos;
				if (takeoffPos != null && this.position().distanceToSqr(Vec3.atLowerCornerOf(takeoffPos)) > 256.0F) {
					this.takeoffPos = null;
				}
			}

			float percentage = this.getHealth() / this.getMaxHealth();
			this.bossInfo.setProgress(percentage);
			if (percentage != this.prevHealthPercentage) {
				HealthStage newStage = HealthStage.getStage(percentage);
				if (newStage.eggGrowthChance > 0.0F && newStage.ordinal() > this.getHealthStage().ordinal()) {
					newStage.awakeNearbyEggs(this);
				}
				this.setHealthStage(newStage);
			}
			this.prevHealthPercentage = percentage;
		} else {
			TimedEndimation takeoff = this.takeoffEndimation;
			takeoff.tick();
			if (takeoff.isMaxed()) {
				this.takeoffMoving = true;
				takeoff.setDecrementing(true);
			} else {
				if (this.takeoffMoving) {
					this.takeoffMoving = takeoff.getTick() > 15;
				} else {
					takeoff.setDecrementing(!this.isFlying());
				}
			}

			this.wingFlapSpeed += this.isMoving() ? (0.5F - this.wingFlapSpeed) * 0.1F : (0.125F - this.wingFlapSpeed) * 0.2F;
			this.prevWingFlap = this.wingFlap;
			this.wingFlap += this.wingFlapSpeed;
		}

		TimedEndimation eggCannonEndimation = this.eggCannonEndimation;
		eggCannonEndimation.setDecrementing(!this.isFiringCannon() && !((this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) || this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT)) && this.getAnimationTick() >= 15));
		eggCannonEndimation.tick();

		TimedEndimation eggMouthEndimation = this.eggMouthEndimation;
		eggMouthEndimation.setDecrementing(!eggCannonEndimation.isMaxed() && this.isNotDroppingEggs());
		eggMouthEndimation.tick();

		TimedEndimation eggCannonFlyingEndimation = this.eggCannonFlyingEndimation;
		eggCannonFlyingEndimation.setDecrementing(!this.isFlying());
		eggCannonFlyingEndimation.tick();

		TimedEndimation flying = this.flyingEndimation;
		flying.setDecrementing(!this.isMoving());
		flying.tick();

		TimedEndimation sleepingEndimation = this.sleepingEndimation;
		sleepingEndimation.setDecrementing(!this.isSleeping());
		sleepingEndimation.tick();

		TimedEndimation healPulseEndimation = this.healPulseEndimation;
		if (healPulseEndimation.isMaxed()) {
			healPulseEndimation.setDecrementing(true);
		}
		healPulseEndimation.tick();

		this.flyingRotations.tick(this.getTargetFlyingRotations());
	}

@Override
	public boolean hurt(DamageSource source, float amount) {
		if (source.getDirectEntity() instanceof AbstractArrow) {
			return false;
		}
		// TODO: Make sure this works properly, perhaps a magic damage tag in blueprint
		return super.hurt(source, source.is(DamageTypeTags.WITCH_RESISTANT_TO) && source.is(DamageTypeTags.BYPASSES_ARMOR) ? amount : amount * (source.is(DamageTypeTags.IS_PROJECTILE) ? 0.05F : 0.1F));
	}

@Nullable
	public BroodEggSack getEggSack(Level world) {
		int eggSackID = this.getEggSackID();
		if (eggSackID >= 0) {
			Entity entity = world.getEntity(eggSackID);
			if (entity instanceof BroodEggSack) {
				return (BroodEggSack) entity;
			}
		}
		return null;
	}

public boolean isEggMouthOpen() {
		return this.eggMouthEndimation.isMaxed();
	}

public boolean isOnLastHealthStage() {
		return this.getHealthStage() == HealthStage.FIVE;
	}

@Override
	public boolean hurt(DamageSource source, float amount) {
		Level world = this.level();
		if (!world.isClientSide) {
			BroodEetle broodEetle = this.getBroodEetle(world);
			if (broodEetle != null && broodEetle.isAlive() && (broodEetle.isEggMouthOpen() || broodEetle.isOnLastHealthStage())) {
				Entity trueSource = source.getEntity();
				LivingEntity livingEntity = trueSource instanceof LivingEntity ? (LivingEntity) trueSource : null;
				if (livingEntity != null) {
					amount += 0.25F * EnchantmentHelper.getDamageBonus(livingEntity.getMainHandItem(), MobType.ARTHROPOD);
				}
				if (broodEetle.attackEntityFromEggSack(source, amount)) {
					if (livingEntity != null) {
						this.doEnchantDamageEffects(livingEntity, broodEetle);
					}
					if (world instanceof ServerLevel) {
						((ServerLevel) world).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, EEBlocks.EETLE_EGG.get().defaultBlockState()), this.getX(), this.getY() + (double) this.getBbHeight() / 1.5D, this.getZ(), 15, this.getBbWidth() / 4.0F, this.getBbHeight() / 4.0F, this.getBbWidth() / 4.0F, 0.05D);
					}
					return true;
				}
			}
		}
		return false;
	}

@Override
	public void tick() {
		Level world = this.level();
		BroodEetle broodEetle = this.getBroodEetle(world);
		if (!world.isClientSide && (broodEetle == null || !broodEetle.isAlive() || broodEetle.getEggSack(world) != this)) {
			this.discard();
		}
	}

@Nullable
	private BroodEetle getBroodEetle(Level world) {
		int broodID = this.getBroodID();
		if (broodID >= 0) {
			Entity entity = world.getEntity(broodID);
			if (entity instanceof BroodEetle) {
				return (BroodEetle) entity;
			}
		}
		return null;
	}

@Override
	protected void addAdditionalSaveData(CompoundTag compound) {
		int broodID = this.getBroodID();
		if (broodID >= 0) {
			compound.putInt("BroodID", broodID);
		}
	}

@Override
	protected void readAdditionalSaveData(CompoundTag compound) {
		if (compound.contains("BroodID", 3)) {
			this.setBroodID(compound.getInt("BroodID"));
		}
	}

@Override
    protected void explode() {
        this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.GENERIC_EXPLODE.value(),
                SoundSource.BLOCKS, 4.0F,
                (1.0F + (this.level().getRandom().nextFloat() - this.level().getRandom().nextFloat()) * 0.2F) * 32.9F);

        if (this.isInWater()) {
            return;
        }

        // TODO 1.21.4: Can likely be rewritten to use the explosion calculator
        var damageSource = Explosion.getDefaultDamageSource(this.level(), this);
        var ex = new ServerExplosion(
                (ServerLevel) this.level(),
                this,
                damageSource,
                new ExplosionDamageCalculator(),
                new Vec3(this.getX(), this.getY(), this.getZ()),
                0.2f,
                false,
                AEConfig.instance().isTinyTntBlockDamageEnabled() ? BlockInteraction.DESTROY_WITH_DECAY
                        : BlockInteraction.KEEP);
        final AABB area = new AABB(this.getX() - 1.5, this.getY() - 1.5f, this.getZ() - 1.5,
                this.getX() + 1.5, this.getY() + 1.5, this.getZ() + 1.5);
        final List<Entity> list = this.level().getEntities(this, area);

        for (Entity e : list) {
            e.hurt(level().damageSources().explosion(ex), 6);
        }

        var pos = new ArrayList<BlockPos>();
        if (AEConfig.instance().isTinyTntBlockDamageEnabled()) {
            this.setPos(this.getX(), this.getY() - 0.25, this.getZ());

            for (int x = (int) (this.getX() - 2); x <= this.getX() + 2; x++) {
                for (int y = (int) (this.getY() - 2); y <= this.getY() + 2; y++) {
                    for (int z = (int) (this.getZ() - 2); z <= this.getZ() + 2; z++) {
                        final BlockPos point = new BlockPos(x, y, z);
                        final BlockState state = this.level().getBlockState(point);
                        final Block block = state.getBlock();

                        if (!state.isAir()) {
                            float strength = (float) (2.3f
                                    - ((x + 0.5f - this.getX()) * (x + 0.5f - this.getX())
                                            + (y + 0.5f - this.getY()) * (y + 0.5f - this.getY())
                                            + (z + 0.5f - this.getZ()) * (z + 0.5f - this.getZ())));

                            final float fluidResistance = !state.getFluidState().isEmpty()
                                    ? state.getFluidState().getExplosionResistance()
                                    : 0f;
                            final float resistance = Math
                                    .max(block.getExplosionResistance(state, this.level(), point, ex), fluidResistance);
                            strength -= (resistance + 0.3F) * 0.11f;

                            if (strength > 0.01 && !state.isAir()) {
                                level().setBlock(point, Blocks.AIR.defaultBlockState(), 3);
                                state.onExplosionHit((ServerLevel) this.level(), point, ex, (stack, dropPoint) -> {
                                    Block.popResource(this.level(), dropPoint, stack);
                                });
                                pos.add(point);
                            }
                        }
                    }
                }
            }
        }
        EventHooks.onExplosionDetonate(this.level(), ex, list, pos);

        AppEng.instance().sendToAllNearExcept(null, this.getX(), this.getY(), this.getZ(), 64, this.level(),
                new MockExplosionPacket(this.getX(), this.getY(), this.getZ()));
    }

@Override
    public void tick() {
        this.updateFluidInteraction();

        this.xo = this.getX();
        this.yo = this.getY();
        this.zo = this.getZ();
        this.setDeltaMovement(this.getDeltaMovement().subtract(0, 0.03999999910593033D, 0));
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(
                this.getDeltaMovement().multiply(0.9800000190734863D, 0.9800000190734863D, 0.9800000190734863D));

        if (this.onGround()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.699999988079071D, 0.699999988079071D, -0.5D));
        }

        if (this.isInWater() && !this.level().isClientSide()) // put out the fuse.
        {
            ItemStack tntStack = AEBlocks.TINY_TNT.stack();

            final ItemEntity item = new ItemEntity(this.level(), this.getX(), this.getY(), this.getZ(),
                    tntStack);

            item.setDeltaMovement(this.getDeltaMovement());
            item.xo = this.xo;
            item.yo = this.yo;
            item.zo = this.zo;

            this.level().addFreshEntity(item);
            this.discard();
        }

        if (this.getFuse() <= 0) {
            this.discard();

            if (!this.level().isClientSide()) {
                this.explode();
            }
        } else {
            this.level().addParticle(ParticleTypes.SMOKE, this.getX(), this.getY(), this.getZ(), 0.0D, 0.0D,
                    0.0D);
        }
        this.setFuse(this.getFuse() - 1);
    }

@Nullable
    @Override
    public LivingEntity getOwner() {
        return this.placedBy;
    }

@Override
    public void writeSpawnData(RegistryFriendlyByteBuf buffer) {
        buffer.writeByte(this.getFuse());
    }

@Override
    public void readSpawnData(RegistryFriendlyByteBuf additionalData) {
        this.setFuse(additionalData.readByte());
    }

@Override
	public void onUpdate(){

		super.onUpdate();

//		if(this.ticksExisted % 20 == 1 && !this.onGround && world.isRemote){
//			// Though this sound does repeat, it stops when it hits the ground.
//			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_HAMMER_FALLING, WizardrySounds.SPELLS, 3.0f, 1.0f, false);
//		}

		if(this.world.isRemote && this.ticksExisted % 3 == 0){
			ParticleBuilder.create(Type.SPARK)
					.pos(this.posX - 0.5d + rand.nextDouble(), this.posY + 2 * rand.nextDouble(), this.posZ - 0.5d + rand.nextDouble())
					.spawn(world);
		}

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		++this.fallTime;
		this.motionY -= 0.03999999910593033D;
		this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		this.motionX *= 0.9800000190734863D;
		this.motionY *= 0.9800000190734863D;
		this.motionZ *= 0.9800000190734863D;

		if(this.onGround){

			this.motionX *= 0.699999988079071D;
			this.motionZ *= 0.699999988079071D;
			this.motionY *= -0.5D;

			this.rotationPitch = 0;
			this.spin = false;

			double seekerRange = Spells.lightning_hammer.getProperty(Spell.EFFECT_RADIUS).doubleValue();

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX,
					this.posY + 1, this.posZ, world);

			int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue();
			while(targets.size() > maxTargets) targets.remove(targets.size() - 1);

			for(EntityLivingBase target : targets){

				if(EntityUtils.isLiving(target) && this.isValidTarget(target)
						&& target.ticksExisted % Spells.lightning_hammer.getProperty(LightningHammer.ATTACK_INTERVAL).floatValue() == 0){

					if(world.isRemote){

						ParticleBuilder.create(Type.LIGHTNING).pos(posX, posY + height - 0.1, posZ) .target(target).spawn(world);

						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height, target.posZ);
					}

					target.playSound(WizardrySounds.ENTITY_HAMMER_ATTACK, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					float damage = Spells.lightning_hammer.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier;

					if(this.getCaster() != null){
						EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(
								this, getCaster(), DamageType.SHOCK), damage);
						EntityUtils.applyStandardKnockback(this, target);
					}else{
						target.attackEntityFrom(DamageSource.MAGIC, damage);
					}
				}
			}

		}else{

			if(spin) this.setRotation(this.rotationYaw, this.rotationPitch + 15);

			List<Entity> collided = world.getEntitiesInAABBexcluding(this, this.getCollisionBoundingBox(), e -> e instanceof EntityLivingBase);

			float damage = Spells.lightning_hammer.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

			for(Entity entity : collided){
				entity.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.SHOCK), damage);
				//if(entity instanceof EntityLivingBase) ((EntityLivingBase)entity).knockBack(this, 2, -this.motionX, -this.motionZ);
			}
		}
	}

@Override
	public boolean processInitialInteract(EntityPlayer player, EnumHand hand){

		if(player == this.getCaster() && ItemArtefact.isArtefactActive(player, WizardryItems.ring_hammer)
				&& player.getHeldItemMainhand().isEmpty() && ticksExisted > 10){

			this.setDead();

			ItemStack hammer = new ItemStack(WizardryItems.lightning_hammer);
			if(!hammer.hasTagCompound()) hammer.setTagCompound(new NBTTagCompound());
			hammer.getTagCompound().setInteger(ItemLightningHammer.DURATION_NBT_KEY, lifetime);
			hammer.setItemDamage(ticksExisted);
			hammer.getTagCompound().setFloat(ItemLightningHammer.DAMAGE_MULTIPLIER_NBT_KEY, damageMultiplier);

			player.setHeldItem(EnumHand.MAIN_HAND, hammer);
			return true;

		}else{
			return super.processInitialInteract(player, hand);
		}
	}

@Override
	public void despawn(){

		this.playSound(WizardrySounds.ENTITY_HAMMER_EXPLODE, 1.0F, 1.0f);

		if(this.world.isRemote){
			this.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, this.posX, this.posY, this.posZ, 0, 0, 0);
		}

		super.despawn();
	}

@Override
	public void readEntityFromNBT(NBTTagCompound nbttagcompound){
		super.readEntityFromNBT(nbttagcompound);
		this.fallTime = nbttagcompound.getByte("Time") & 255;
		this.spin = nbttagcompound.getBoolean("Spin");
	}

@Override
	public void writeEntityToNBT(NBTTagCompound nbttagcompound){
		super.writeEntityToNBT(nbttagcompound);
		nbttagcompound.setByte("Time", (byte)this.fallTime);
		nbttagcompound.setBoolean("Spin", spin);
	}

public void onUpdate(){

		if(this.ticksExisted > lifetime && lifetime != -1){
			this.despawn();
		}

		super.onUpdate();

	}

public void despawn(){
		this.setDead();
	}

@Nullable
	public EntityLivingBase getCaster(){ // Kept despite the above method because it returns an EntityLivingBase

		Entity entity = EntityUtils.getEntityByUUID(world, getOwnerId());

		if(entity != null && !(entity instanceof EntityLivingBase)){ // Should never happen
			Wizardry.logger.warn("{} has a non-living owner!", this);
			entity = null;
		}

		return (EntityLivingBase)entity;
	}

public void setCaster(@Nullable EntityLivingBase caster){
		this.casterUUID = caster == null ? null : caster.getUniqueID();
	}

@Override
	protected void writeEntityToNBT(NBTTagCompound nbttagcompound){
		if(casterUUID != null){
			nbttagcompound.setUniqueId("casterUUID", casterUUID);
		}
		nbttagcompound.setInteger("lifetime", lifetime);
		nbttagcompound.setFloat("damageMultiplier", damageMultiplier);
	}

@Override
	protected void readEntityFromNBT(NBTTagCompound nbttagcompound){
