protected boolean spawnConstruct(World world, double x, double y, double z, @Nullable EnumFacing side, @Nullable EntityLivingBase caster, SpellModifiers modifiers){

		if(!world.isRemote){
			// Creates a new construct using the supplied factory
			T construct = constructFactory.apply(world);
			// Sets the position of the construct (and initialises its bounding box)
			construct.setPosition(x, y, z);
			// Sets the various parameters
			construct.setCaster(caster);
			construct.lifetime = permanent ? -1 : (int)(getProperty(DURATION).floatValue() * modifiers.get(WizardryItems.duration_upgrade));
			construct.damageMultiplier = modifiers.get(SpellModifiers.POTENCY);
			if(construct instanceof EntityScaledConstruct) ((EntityScaledConstruct)construct).setSizeMultiplier(modifiers.get(WizardryItems.blast_upgrade));
			addConstructExtras(construct, side, caster, modifiers);
			// Prevents overlapping of multiple constructs of the same type. Since we have an instance here this is
			// very simple. The trade-off is that we have to create the entity before the spell fails, but unless
			// world.spawnEntity(...) is called, its scope is limited to this method so it should be fine.
			// Needs to be last in case addConstructExtras modifies the bounding box
			if(!allowOverlap && !world.getEntitiesWithinAABB(construct.getClass(), construct.getEntityBoundingBox()).isEmpty()) return false;
			// Spawns the construct in the world
			world.spawnEntity(construct);
		}

		return true;
	}

@Override
	protected boolean spawnConstruct(World world, double x, double y, double z, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){
		if(!world.canBlockSeeSky(new BlockPos(x, y, z))) return false;
		return super.spawnConstruct(world, x, y + 50, z, side, caster, modifiers);
	}

@Override
	protected void addConstructExtras(EntityHammer construct, EnumFacing side, EntityLivingBase caster, SpellModifiers modifiers){
		construct.motionY = -2;
	}

@Override
	public void onUpdate(ItemStack stack, World world, Entity entity, int slot, boolean selected){
		int damage = stack.getItemDamage();
		if(damage > stack.getMaxDamage()) InventoryUtils.replaceItemInInventory(entity, slot, stack, ItemStack.EMPTY);
		stack.setItemDamage(damage + 1);
	}

@Override
	public ActionResult<ItemStack> onItemRightClick(World world, EntityPlayer player, EnumHand hand){

		ItemStack stack = player.getHeldItem(hand);

		if(!world.isRemote){
			EntityHammer hammer = new EntityHammer(world);
			Vec3d look = player.getLookVec();
			Vec3d vec = player.getPositionEyes(1).add(look);
			hammer.setPositionAndRotation(vec.x, vec.y - hammer.height/2, vec.z, player.rotationYawHead - 90, 0);
			// For some reason the above method insists on clamping the pitch to between -90 and 90
			hammer.rotationPitch = 180 + player.rotationPitch;
			hammer.prevRotationPitch = hammer.rotationPitch;

			float attackStrength = player.getCooledAttackStrength(0);
			double speed = THROW_SPEED * attackStrength; // Throw distance depends on the attack meter
			hammer.addVelocity(look.x * speed, look.y * speed, look.z * speed);
			hammer.lifetime = stack.getMaxDamage() - stack.getItemDamage();
			hammer.setCaster(player);
			hammer.damageMultiplier = getDamageMultiplier(stack);
			hammer.spin = true;
			world.spawnEntity(hammer);
		}

		EntityUtils.playSoundAtPlayer(player, WizardrySounds.ENTITY_HAMMER_THROW, 1.0F, 0.8f);

		//player.swingArm(hand);

		// Use this instead of stack.shrink so it works regardless of whether the player is in creative mode or not
		player.setHeldItem(hand, ItemStack.EMPTY);

		return ActionResult.newResult(EnumActionResult.SUCCESS, stack);
	}

@Override
	public int getMaxDamage(ItemStack stack){
		if(stack.hasTagCompound() && stack.getTagCompound().hasKey(DURATION_NBT_KEY)){
			return stack.getTagCompound().getInteger(DURATION_NBT_KEY);
		}
		return super.getMaxDamage(stack);
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		BlockPos pos = this.getPosition().down(1);
		IBlockState blockState = this.world.getBlockState(pos);

		if(!this.world.isRemote) {
			if(blockState.getBlock() == Blocks.AIR || (this.hasPlayerOwner() && !blockState.isSideSolid(this.world, pos, EnumFacing.UP))) {
				this.setDead();
			}

			Entity owner = this.getPlayerOwner();

			if(this.hasPlayerOwner() && (owner == null || owner.getDistance(this) > 32.0D)) {
				this.setHealth(0);
			} else if(owner instanceof EntityPlayer) {
				EntityPlayer player = (EntityPlayer) owner;
				if(!ItemRingOfSummoning.isRingActive(player)) {
					this.setHealth(0);
				}
			}

			if(this.despawnTicks >= 150) {
				this.setHealth(0);
			} else {
				if(this.spawnTicks >= 40) {
					this.despawnTicks++;
				}
			}
		}

		if(this.deathTicks > 0) {
			this.yOffset = -this.deathTicks / 40.0F;
		} else if(this.spawnTicks >= 40) {
			this.yOffset = 0.0F;
		}

		if(this.isEntityAlive()) {
			if(this.spawnTicks >= 4) {
				List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox());
				for(EntityLivingBase target : targets) {

					boolean isValidTarget;
					if(this.hasPlayerOwner()) {
						isValidTarget = target != this && target != this.getPlayerOwner() && (target instanceof EntityMob || target instanceof IMob);
					} else {
						isValidTarget = target instanceof EntityPlayer;
					}
					if(isValidTarget) {
						target.setInWeb();

						if(target.hurtResistantTime < 10) {
							DamageSource damageSource;
							Entity owner = this.getPlayerOwner();
							if(owner != null) {
								damageSource = new EntityDamageSourceIndirect("mob", this, owner);
							} else {
								damageSource = DamageSource.causeMobDamage(this);
							}

							target.attackEntityFrom(damageSource, (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());

							if(this.attackSwing <= 0) {
								this.attackSwing = 20;
							}
						}
					}
				}
			}

			if(this.spawnTicks < 40) {
				this.spawnTicks++;
				this.yOffset = -1 + this.spawnTicks / 40.0F;
			} else {
				this.yOffset = 0.0F;
			}

			if(this.attackSwing > 0) {
				this.attackSwing--;
			}
		}

		if(this.world.isRemote && this.rand.nextInt(this.yOffset < 0.0F ? 2 : 8) == 0) {
			if(blockState.getBlock() != Blocks.AIR) {
				double px = this.posX;
				double py = this.posY;
				double pz = this.posZ;
				for (int i = 0, amount = 2 + this.rand.nextInt(this.yOffset < 0.0F ? 8 : 3); i < amount; i++) {
					double ox = this.rand.nextDouble() * 0.1F - 0.05F;
					double oz = this.rand.nextDouble() * 0.1F - 0.05F;
					double motionX = this.rand.nextDouble() * 0.2 - 0.1;
					double motionY = this.rand.nextDouble() * 0.1 + 0.1;
					double motionZ = this.rand.nextDouble() * 0.2 - 0.1;
					this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, px + ox, py, pz + oz, motionX, motionY, motionZ, Block.getStateId(blockState));
				}
			}
		}
	}

public void setPlayerOwner(@Nullable EntityPlayer owner) {
		this.owner = owner;
		this.ownerUUID = owner == null ? null : owner.getUniqueID();
		this.getDataManager().set(OWNER_ID, owner == null ? -1 : owner.getEntityId());
	}

@Nullable
	public Entity getPlayerOwner() {
		if(!this.world.isRemote) {
			if(this.owner != null && this.owner.getUniqueID().equals(this.ownerUUID)) {
				return this.owner;
			} else {
				this.owner = this.ownerUUID == null ? null : this.getEntityByUUID(this.ownerUUID);
				return this.owner;
			}
		} else {
			if(this.owner != null && this.owner.getEntityId() != this.getDataManager().get(OWNER_ID)) {
				return this.owner;
			} else {
				int id = this.getDataManager().get(OWNER_ID);
				this.owner = id < 0 ? null : this.world.getEntityByID(id);
				return this.owner;
			}
		}
	}

private Entity getEntityByUUID(UUID uuid) {
		for (int i = 0; i < this.world.loadedEntityList.size(); ++i) {
			Entity entity = (Entity)this.world.loadedEntityList.get(i);
			if (uuid.equals(entity.getUniqueID())) {
				return entity;
			}
		}
		return null;
	}

