@Override
	protected void arrowHit(EntityLivingBase living) {
		switch(this.getArrowType()) {
		case ANGLER_POISON:
			living.addPotionEffect(new PotionEffect(MobEffects.POISON, 200, 2));
			break;
		case OCTINE:
			if(living.isBurning()) {
				living.setFire(9);
			} else {
				living.setFire(5);
			}
			break;
		case BASILISK:
			if(living instanceof EntityChiromawMatriarch)
				break;
			if(living.isNonBoss()) {
				living.addPotionEffect(ElixirEffectRegistry.EFFECT_PETRIFY.createEffect(100, 1));
			} else {
				living.addPotionEffect(ElixirEffectRegistry.EFFECT_PETRIFY.createEffect(40, 1));
			}
			break;
		case WORM:
			if (!getEntityWorld().isRemote) {
				EntityTinySludgeWormHelper worm = new EntityTinySludgeWormHelper(getEntityWorld());
				worm.setLocationAndAngles(this.posX, this.posY, this.posZ, this.rotationYaw, this.rotationPitch);
				worm.setAttackTarget(living);
				if(this.shootingEntity instanceof EntityPlayer) {
					worm.setOwnerId(this.shootingEntity.getUniqueID());
				}
				getEntityWorld().spawnEntity(worm);
				this.setDead();
			}
			break;
		case SHOCK:
			if(!this.world.isRemote) {
				this.world.spawnEntity(new EntityShock(this.world, this, living, 0, this.isWet() || this.isInWater() || this.world.isRainingAt(this.getPosition().up())));
			}
			break;
		case CHIROMAW_BARB:
			if(living instanceof EntityChiromawMatriarch)
				break;
			if(living.isNonBoss()) {
				living.addPotionEffect(ElixirEffectRegistry.EFFECT_PETRIFY.createEffect(40, 1));
			} 
			break;
		case CHIROMAW_SHOCK_BARB:
			if(!this.world.isRemote) {
				this.world.spawnEntity(new EntityShock(this.world, this, living, 0, this.isWet() || this.isInWater() || this.world.isRainingAt(this.getPosition().up())));
			}
			if(living instanceof EntityChiromawMatriarch)
				break;
			if(living.isNonBoss()) {
				living.addPotionEffect(ElixirEffectRegistry.EFFECT_PETRIFY.createEffect(40, 1));
			} 
			break;
		default:
		}
	}

@Override
	public IMessage process(MessageContext ctx) {
		super.process(ctx);

		if(ctx.side == Side.CLIENT) {
			List<Entity> entities = this.getEntities();

			for(int i = 0; i < entities.size() / 2; i++) {
				Entity from = entities.get(i * 2);
				Entity to = entities.get(i * 2 + 1);

				if(from != null && to != null) {
					Particle particle = BLParticles.LIGHTNING_ARC.create(from.world, from.posX, from.posY + from.height / 2, from.posZ, 
							ParticleArgs.get().withColor(0.3f, 0.5f, 1.0f, 0.9f).withData(new Vec3d(to.posX, to.posY + to.height / 2, to.posZ)));

					BatchedParticleRenderer.INSTANCE.addParticle(DefaultParticleBatches.BEAM, particle);

					from.world.playSound(from.posX, from.posY, from.posZ, SoundRegistry.ZAP, SoundCategory.PLAYERS, 1, 1, false);
				}
			}
		}

		return null;
	}
